   945          /*
   946           * For DLT_PPI captures, generate a check of the per-packet
   947           * DLT value to make sure it's DLT_IEEE802_11.
   948           *
   949           * XXX - TurboCap cards use DLT_PPI for Ethernet.
   950           * Can we just define some DLT_ETHERNET_WITH_PHDR pseudo-header
   951           * with appropriate Ethernet information and use that rather
   952           * than using something such as DLT_PPI where you don't know
   953           * the link-layer header type until runtime, which, in the
   954           * general case, would force us to generate both Ethernet *and*
   955           * 802.11 code (*and* anything else for which PPI is used)
   956           * and choose between them early in the BPF program?
   957           */
   958          ppi_dlt_check = gen_ppi_dlt_check(cstate);
   959          if (ppi_dlt_check != NULL)
   960                  gen_and(ppi_dlt_check, p);
   961
   962          backpatch(p, gen_retblk(cstate, cstate->snaplen));
   963          p->sense = !p->sense;
   964          backpatch(p, gen_retblk(cstate, 0));
   965          cstate->ic.root = p->head;
   966  }
