   968  void
   969  gen_and(struct block *b0, struct block *b1)
   970  {
   971          backpatch(b0, b1->head);
   972          b0->sense = !b0->sense;
   973          b1->sense = !b1->sense;
   974          merge(b1, b0);
   975          b1->sense = !b1->sense;
   976          b1->head = b0->head;
   977  }
   978
   979  void
   980  gen_or(struct block *b0, struct block *b1)
   981  {
   982          b0->sense = !b0->sense;
   983          backpatch(b0, b1->head);
   984          b0->sense = !b0->sense;
   985          merge(b1, b0);
   986          b1->head = b0->head;
   987  }
